fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut iter = txt.chars();

    // Must be non-empty
    let mut prev = match iter.next() {
        Some(c) => c,
        None => return false,
    };

    // Track the previous character while walking to the end
    let mut last = prev;
    for c in iter {
        prev = last;
        last = c;
    }

    // Last character must be an ASCII letter
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // If length is 1 char, ok; otherwise preceding char must be a space
    if txt.chars().count() == 1 {
        true
    } else {
        prev == ' '
    }
}